## Common Patterns

### Repository Abstraction

Create a generic interface that works with any ORM:

```typescript
// common/interfaces/repository.interface.ts
export interface IRepository<T> {
  findAll(): Promise<T[]>;
  findOne(id: string | number): Promise<T | null>;
  create(data: Partial<T>): Promise<T>;
  update(id: string | number, data: Partial<T>): Promise<T>;
  delete(id: string | number): Promise<void>;
}

// Implementation can use TypeORM, Prisma, or Drizzle
@Injectable()
export class UsersRepository implements IRepository<User> {
  constructor(private prisma: PrismaService) {}

  async findAll() {
    return this.prisma.user.findMany();
  }

  // ... other methods
}
```

### Database Health Check

```typescript
// health/database.health.ts
import { Injectable } from '@nestjs/common';
import {
  HealthIndicator,
  HealthIndicatorResult,
  HealthCheckError,
} from '@nestjs/terminus';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class DatabaseHealthIndicator extends HealthIndicator {
  constructor(private prisma: PrismaService) {
    super();
  }

  async isHealthy(key: string): Promise<HealthIndicatorResult> {
    try {
      await this.prisma.$queryRaw`SELECT 1`;
      return this.getStatus(key, true);
    } catch (error) {
      throw new HealthCheckError(
        'Database check failed',
        this.getStatus(key, false, { message: error.message }),
      );
    }
  }
}

// health/health.controller.ts
@Controller('health')
export class HealthController {
  constructor(
    private health: HealthCheckService,
    private db: DatabaseHealthIndicator,
  ) {}

  @Get()
  @HealthCheck()
  check() {
    return this.health.check([
      () => this.db.isHealthy('database'),
    ]);
  }
}
```

### Soft Delete Pattern

```typescript
// TypeORM
@Entity()
export class User {
  @DeleteDateColumn()
  deletedAt?: Date;
}

// Prisma - manual implementation
model User {
  deletedAt DateTime?
}

// Service
async softDelete(id: string) {
  return this.prisma.user.update({
    where: { id },
    data: { deletedAt: new Date() },
  });
}

async findActive() {
  return this.prisma.user.findMany({
    where: { deletedAt: null },
  });
}

// Drizzle
async softDelete(id: string) {
  return this.db
    .update(schema.users)
    .set({ deletedAt: new Date() })
    .where(eq(schema.users.id, id));
}
