## Pipes

Pipes transform input data or validate it before it reaches the route handler.

### Built-in Pipes

```typescript
import {
  ParseIntPipe,
  ParseBoolPipe,
  ParseArrayPipe,
  ParseUUIDPipe,
  ParseEnumPipe,
  DefaultValuePipe,
  ParseFloatPipe,
} from '@nestjs/common';

@Controller('users')
export class UsersController {
  // ParseIntPipe
  @Get(':id')
  findOne(@Param('id', ParseIntPipe) id: number) {
    return this.usersService.findOne(id);
  }

  // ParseUUIDPipe with version
  @Get(':uuid')
  findByUuid(@Param('uuid', new ParseUUIDPipe({ version: '4' })) uuid: string) {}

  // ParseBoolPipe
  @Get()
  findAll(@Query('active', ParseBoolPipe) active: boolean) {}

  // DefaultValuePipe
  @Get()
  findPaginated(
    @Query('page', new DefaultValuePipe(1), ParseIntPipe) page: number,
    @Query('limit', new DefaultValuePipe(10), ParseIntPipe) limit: number,
  ) {}

  // ParseArrayPipe
  @Get()
  findByIds(
    @Query('ids', new ParseArrayPipe({ items: Number, separator: ',' }))
    ids: number[],
  ) {}

  // ParseEnumPipe
  @Get()
  findByStatus(
    @Query('status', new ParseEnumPipe(UserStatus)) status: UserStatus,
  ) {}
}
```

### Custom Validation Pipe

```typescript
import {
  PipeTransform,
  Injectable,
  BadRequestException,
} from '@nestjs/common';

@Injectable()
export class ParseDatePipe implements PipeTransform<string, Date> {
  transform(value: string): Date {
    const date = new Date(value);

    if (isNaN(date.getTime())) {
      throw new BadRequestException(`Invalid date: ${value}`);
    }

    return date;
  }
}

// Usage
@Get()
findByDate(@Query('date', ParseDatePipe) date: Date) {}
```

### Schema Validation Pipe (Zod)

```typescript
import { z, ZodSchema } from 'zod';

@Injectable()
export class ZodValidationPipe implements PipeTransform {
  constructor(private schema: ZodSchema) {}

  transform(value: unknown) {
    const result = this.schema.safeParse(value);

    if (!result.success) {
      throw new BadRequestException({
        message: 'Validation failed',
        errors: result.error.format(),
      });
    }

    return result.data;
  }
}

// Usage
const createUserSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
});

@Post()
create(
  @Body(new ZodValidationPipe(createUserSchema))
  createUserDto: z.infer<typeof createUserSchema>,
) {}
```

### Applying Pipes

```typescript
// Parameter level
@Get(':id')
findOne(@Param('id', ParseIntPipe) id: number) {}

// Method level
@Post()
@UsePipes(ValidationPipe)
create(@Body() dto: CreateUserDto) {}

// Controller level
@Controller('users')
@UsePipes(new ValidationPipe({ transform: true }))
export class UsersController {}

// Global level (main.ts)
app.useGlobalPipes(
  new ValidationPipe({
    whitelist: true,
    forbidNonWhitelisted: true,
    transform: true,
  }),
);

// Global with DI
@Module({
  providers: [
    {
      provide: APP_PIPE,
      useValue: new ValidationPipe({ whitelist: true }),
    },
  ],
})
export class AppModule {}
```

