## DTO Best Practices

### Basic DTO Structure

```typescript
// dto/create-user.dto.ts
import {
  IsEmail,
  IsString,
  MinLength,
  MaxLength,
  IsOptional,
  Matches,
} from 'class-validator';

export class CreateUserDto {
  @IsEmail({}, { message: 'Invalid email format' })
  email: string;

  @IsString()
  @MinLength(8, { message: 'Password must be at least 8 characters' })
  @MaxLength(32)
  @Matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/, {
    message: 'Password must contain uppercase, lowercase, and number',
  })
  password: string;

  @IsOptional()
  @IsString()
  @MaxLength(100)
  name?: string;
}
```

### Nested Object Validation

```typescript
import { Type } from 'class-transformer';
import { ValidateNested, IsArray } from 'class-validator';

class AddressDto {
  @IsString()
  street: string;

  @IsString()
  city: string;

  @IsString()
  @Matches(/^\d{5}(-\d{4})?$/)
  zipCode: string;
}

export class CreateUserDto {
  @IsEmail()
  email: string;

  @ValidateNested()
  @Type(() => AddressDto)  // Required for nested object validation
  address: AddressDto;

  @IsArray()
  @ValidateNested({ each: true })  // Validate each item in array
  @Type(() => AddressDto)
  addresses: AddressDto[];
}
```

### Conditional Validation

```typescript
import { ValidateIf, IsNotEmpty, IsString } from 'class-validator';

export class PaymentDto {
  @IsString()
  paymentType: 'card' | 'bank';

  @ValidateIf((o) => o.paymentType === 'card')
  @IsNotEmpty()
  @IsCreditCard()
  cardNumber?: string;

  @ValidateIf((o) => o.paymentType === 'bank')
  @IsNotEmpty()
  @IsIBAN()
  iban?: string;
}
```

### Validation Groups

```typescript
export class CreateUserDto {
  @IsEmail({}, { groups: ['create', 'update'] })
  email: string;

  @IsString({ groups: ['create'] })
  @MinLength(8, { groups: ['create'] })
  password: string;

  @IsOptional({ groups: ['update'] })
  @IsString({ groups: ['update'] })
  name?: string;
}

// Usage
@Post()
@UsePipes(new ValidationPipe({ groups: ['create'] }))
create(@Body() dto: CreateUserDto) {}

@Patch(':id')
@UsePipes(new ValidationPipe({ groups: ['update'] }))
update(@Param('id') id: string, @Body() dto: CreateUserDto) {}
```

