### Array Validators

```typescript
// Array of specific type
@IsArray()
@IsString({ each: true })  // Validate each element
@ArrayMinSize(1)
@ArrayMaxSize(10)
@ArrayUnique()
tags: string[];

// Array of numbers
@IsArray()
@IsInt({ each: true })
@ArrayMinSize(1)
