## Class-Transformer Usage

### Basic Transformation

```typescript
import { Transform, Type, Exclude, Expose } from 'class-transformer';

export class UserResponseDto {
  @Expose()
  id: number;

  @Expose()
  email: string;

  @Exclude()
  password: string;  // Never sent to client

  @Transform(({ value }) => value.toLowerCase())
  @Expose()
  username: string;

  @Type(() => Date)
  @Expose()
  createdAt: Date;
}
```

### Transform Decorators

```typescript
// Trim whitespace
@Transform(({ value }) => value?.trim())
@IsString()
name: string;

// Convert to lowercase
@Transform(({ value }) => value?.toLowerCase())
@IsEmail()
email: string;

// Parse JSON string
@Transform(({ value }) => {
  try {
    return typeof value === 'string' ? JSON.parse(value) : value;
  } catch {
    return value;
  }
})
metadata: Record<string, any>;

// Default value
@Transform(({ value }) => value ?? 'default')
status: string;

// Convert array from comma-separated string
@Transform(({ value }) =>
  typeof value === 'string' ? value.split(',').map((v) => v.trim()) : value,
)
@IsArray()
@IsString({ each: true })
tags: string[];
```

### Exclude/Expose Strategies

```typescript
import { Exclude, Expose, plainToInstance } from 'class-transformer';

// Exclude by default, only expose marked properties
@Exclude()
export class UserResponseDto {
  @Expose()
  id: number;

  @Expose()
  email: string;

  // password is excluded automatically

  @Expose({ groups: ['admin'] })
  role: string;  // Only exposed for admin group
}

// Transform entity to DTO
const user = await this.usersRepository.findOne(id);
return plainToInstance(UserResponseDto, user, {
  excludeExtraneousValues: true,
  groups: ['admin'], // Include admin-only fields
});
```

### Serialization Interceptor

```typescript
import { ClassSerializerInterceptor } from '@nestjs/common';

// Global serialization
app.useGlobalInterceptors(new ClassSerializerInterceptor(app.get(Reflector)));

// Or per-controller
@Controller('users')
@UseInterceptors(ClassSerializerInterceptor)
export class UsersController {
